/// <reference types="react" />
import type { TableCell, TableRow, TableColumn } from '../../types/shared-table-types.js';
/** Factory function which is expected to return a <TableUserActions> component for a given column. */
export type ColumnActionsProvider = (column: TableColumn) => React.ReactElement;
/** Factory function which is expected to return a <TableUserActions> component for a given column. */
export type CellActionsProvider = (props: {
    cell: TableCell;
    row: TableRow;
    column: TableColumn;
}) => React.ReactElement;
/** Factory function which is expected to return a <TableUserActions> component for a given row. */
export type RowActionsProvider = (props: {
    row: TableRow;
}) => React.ReactElement;
/** Configuration containing all user action providers for table columns. */
export type UserActionConfig = {
    /** User action provider used as fallback when no provider is specified for a specific column. */
    defaultColumnActionProvider: ColumnActionsProvider | null;
    /** Column names mapped to specific user action providers. */
    columnActionProviders: {
        [column: string]: ColumnActionsProvider;
    };
    /** User action provider used as fallback when no provider is specified for a specific column. */
    defaultCellActionProvider: CellActionsProvider | null;
    /** Column names mapped to specific user action providers. */
    cellActionProviders: {
        [column: string]: CellActionsProvider;
    };
    rowActionsProvider: RowActionsProvider | null;
};
/** Extension interface for type `Column` required for using the `useUserActions` plugin hook. */
export interface UseColumnUserActionsProps {
    /** Whether sorting is accessible via column user actions menu (workaround for disabling default sorting). */
    canSortViaUserAction?: boolean;
}
/** Extension interface for the TableOptions when useUserActions plugin is used. */
export interface UseUserActionsOptions {
    /** Config object containing all configured user action providers. */
    userActions?: UserActionConfig;
}
/** Extension interface for the TableState when useUserActions plugin is used. */
export type UseUserActionsState = UseUserActionsOptions;
